import os
from typing import Dict, Any
import boto3
from botocore.exceptions import ClientError

class StructuredDocumentValidator:
    def __init__(self, required_fields: Dict[str, float]):
        """
        Initialize the validator with required fields and their minimum confidence scores.

        Args:
            required_fields: Dictionary of field names and their minimum confidence scores (0.0-1.0)
        """
        self.required_fields = required_fields
        self.textract = boto3.client(
            'textract',
            aws_access_key_id=os.getenv('AWS_ACCESS_KEY_ID'),
            aws_secret_access_key=os.getenv('AWS_SECRET_ACCESS_KEY'),
            region_name=os.getenv('AWS_REGION', 'us-east-1')
        )

    def validate_document(self, document_bytes: bytes) -> Dict[str, Any]:
        """
        Validate a document using Amazon Textract and check required fields and confidence scores.

        Args:
            document_bytes: Bytes of the document image or PDF

        Returns:
            Dictionary containing validation results, extracted fields, and confidence scores
        """
        try:
            # Call Amazon Textract AnalyzeDocument API with FORMS feature
            response = self.textract.analyze_document(
                Document={'Bytes': document_bytes},
                FeatureTypes=['FORMS']
            )

            # Extract key-value pairs from the response
            key_values = {}
            for block in response['Blocks']:
                if block['BlockType'] == 'KEY_VALUE_SET' and 'KEY' in block['EntityTypes']:
                    key = None
                    value = None
                    for relationship in block.get('Relationships', []):
                        if relationship['Type'] == 'VALUE':
                            for value_id in relationship['Ids']:
                                value_block = next(
                                    b for b in response['Blocks'] if b['Id'] == value_id
                                )
                                if value_block['BlockType'] == 'WORD':
                                    value = value_block.get('Text', '')
                                elif value_block['BlockType'] == 'SELECTION_ELEMENT':
                                    value = 'SELECTED' if value_block.get('SelectionStatus') == 'SELECTED' else 'NOT_SELECTED'
                        elif relationship['Type'] == 'CHILD':
                            for child_id in relationship['Ids']:
                                child_block = next(
                                    b for b in response['Blocks'] if b['Id'] == child_id
                                )
                                if child_block['BlockType'] == 'WORD':
                                    key = child_block.get('Text', '')
                    if key and value is not None:
                        key_values[key] = {
                            'value': value,
                            'confidence': block.get('Confidence', 0.0)
                        }

            # Validate required fields and confidence scores
            validation_results = {}
            all_fields_valid = True

            for field, min_confidence in self.required_fields.items():
                field_data = key_values.get(field)
                if field_data is None:
                    validation_results[field] = {
                        'present': False,
                        'confidence': 0.0,
                        'valid': False,
                        'message': f"Field '{field}' not found in document"
                    }
                    all_fields_valid = False
                else:
                    confidence = field_data['confidence']
                    is_valid = confidence >= min_confidence
                    validation_results[field] = {
                        'present': True,
                        'value': field_data['value'],
                        'confidence': confidence,
                        'valid': is_valid,
                        'message': f"Confidence {confidence:.2f} meets minimum {min_confidence:.2f}" if is_valid
                                   else f"Confidence {confidence:.2f} below minimum {min_confidence:.2f}"
                    }
                    if not is_valid:
                        all_fields_valid = False

            return {
                'is_valid': all_fields_valid,
                'fields': validation_results,
                'raw_response': response
            }

        except ClientError as e:
            raise Exception(f"Amazon Textract API error: {str(e)}")
        except Exception as e:
            raise Exception(f"Document validation failed: {str(e)}")
